/**
 * Unit tests for the dispatch reconciler (T5 — standalone-executor-hardening).
 *
 * Reconciler state machine coverage:
 *   1. No stuck tasks → returns { reEnqueued: 0, blocked: 0 }.
 *   2. A task with execution_handle older than EXECUTION_DEADLINE_MS → re-enqueued.
 *   3. A task with execution_handle but recent last_updated_at → NOT re-enqueued.
 *   4. A task with no execution_handle → NOT touched.
 *   5. A task whose retry count >= MAX_RETRIES → set to blocked.
 *   6. Re-enqueue calls broker.register(handle, freshNonce) before executor.submit().
 *   7. Re-enqueue calls executor.submit() with correct fields.
 *   8. Reconciler is idempotent: blocked tasks are not re-enqueued.
 */

import {
  describe,
  it,
  expect,
  beforeEach,
  afterEach,
  vi,
} from "vitest";
import {
  mkdtempSync,
  writeFileSync,
  mkdirSync,
  rmSync,
  readFileSync,
} from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { stringify as yamlStringify, parse as yamlParse } from "yaml";

import { runDispatchReconciler } from "../src/loop/dispatch-reconciler.js";
import type { Task } from "../src/task/types.js";

// ── Fake executor ─────────────────────────────────────────────────────────────

interface SubmitCall {
  handle: string;
  nonce: string;
  taskId: string;
}

class FakeExecutor {
  submitCalls: SubmitCall[] = [];
  shouldThrow = false;

  async submit(input: { handle: string; nonce: string; taskId: string; [key: string]: unknown }): Promise<string> {
    if (this.shouldThrow) throw new Error("executor error");
    this.submitCalls.push({ handle: input.handle, nonce: input.nonce, taskId: input.taskId });
    return input.handle;
  }

  async readResult(_handle: string) {
    return { terminal_status: "failed" as const, blocked_reason: "handle_not_found" };
  }

  async ack(_handle: string): Promise<void> { /* no-op */ }
}

// ── Fake broker ───────────────────────────────────────────────────────────────

interface RegisterCall {
  handle: string;
  nonce: string;
}

class FakeBroker {
  registerCalls: RegisterCall[] = [];
  shouldThrow = false;

  async register(handle: string, nonce: string, _meta: unknown): Promise<void> {
    if (this.shouldThrow) throw new Error("broker error");
    this.registerCalls.push({ handle, nonce });
  }

  async ack(_handle: string): Promise<void> { /* no-op */ }
  async nack(_handle: string): Promise<void> { /* no-op */ }
  async listCompleted() { return []; }
  getCallbackUrl(): string { return "http://broker:7000/callback"; }
  inFlightCount(): number { return 0; }
  registrySize(): number { return 0; }
  start(): Promise<number> { return Promise.resolve(7000); }
  stop(): Promise<void> { return Promise.resolve(); }
}

// ── Test helpers ──────────────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeTmpDir(prefix: string): string {
  const dir = mkdtempSync(join(tmpdir(), prefix));
  tmpDirs.push(dir);
  return dir;
}

/**
 * Build a minimal workspace directory with a task YAML.
 */
function makeWorkspace(
  wsRoot: string,
  featureId: string,
  task: Partial<Task> & { id: string },
): string {
  const tasksDir = join(wsRoot, "docs", "features", featureId, "tasks");
  mkdirSync(tasksDir, { recursive: true });

  // workspace.yaml needed for config resolution.
  // repos[].github matches what resolveRepoGitUrl reads.
  writeFileSync(
    join(wsRoot, "workspace.yaml"),
    yamlStringify({
      workspace_id: "test-ws",
      management_repo: "mgmt",
      repos: [
        {
          id: "impl",
          github: "git@github.com:org/impl.git",
          base_branch: "main",
        },
        {
          id: "mgmt",
          github: "git@github.com:org/mgmt.git",
          base_branch: "main",
        },
      ],
    }),
    "utf-8",
  );

  const fullTask: Task = {
    id: task.id,
    title: task.title ?? "Test Task",
    repo: task.repo ?? "impl",
    status: task.status ?? "in_progress",
    depends_on: task.depends_on ?? [],
    blocked_reason: task.blocked_reason ?? null,
    blocked_context: task.blocked_context ?? null,
    branch: task.branch ?? `feature/test-${task.id}`,
    execution: task.execution ?? {
      actor_type: "agent",
      last_updated_by: "test@test.com",
      last_updated_at: new Date(Date.now() - 3 * 60 * 60 * 1000).toISOString(), // 3h ago
    },
    execution_handle: task.execution_handle,
    pr: task.pr ?? { url: "", status: "not_created" },
    workspace_pr: task.workspace_pr ?? null,
    log: task.log ?? [],
  };

  writeFileSync(
    join(tasksDir, `${task.id}.yaml`),
    yamlStringify(fullTask),
    "utf-8",
  );

  return join(tasksDir, `${task.id}.yaml`);
}

function emitCapture(): { events: Record<string, unknown>[]; emit: (e: Record<string, unknown>) => void } {
  const events: Record<string, unknown>[] = [];
  return { events, emit: (e) => events.push(e) };
}

afterEach(() => {
  for (const d of tmpDirs) {
    try { rmSync(d, { recursive: true, force: true }); } catch { /* ignore */ }
  }
  tmpDirs.length = 0;
});

// ── Tests ─────────────────────────────────────────────────────────────────────

describe("runDispatchReconciler", () => {
  let executor: FakeExecutor;
  let broker: FakeBroker;

  beforeEach(() => {
    executor = new FakeExecutor();
    broker = new FakeBroker();
    // Suppress EXECUTION_DEADLINE_MS env override to use the default (2h).
    delete process.env.EXECUTION_DEADLINE_MS;
    delete process.env.DISPATCH_RECONCILE_MAX_RETRIES;
  });

  // ── 1. No stuck tasks ─────────────────────────────────────────────────────

  it("returns zero counts when no tasks are stuck", async () => {
    const wsRoot = makeTmpDir("reconciler-empty-");
    const { emit } = emitCapture();

    const result = await runDispatchReconciler({
      workspaceRoots: [wsRoot],
      executor: executor as never,
      broker: broker as never,
      workspacesDir: "/workspaces",
      callbackUrl: "http://broker:7000/callback",
      gitAuthorEmail: "test@test.com",
      emit,
    });

    expect(result.reEnqueued).toBe(0);
    expect(result.blocked).toBe(0);
    expect(executor.submitCalls).toHaveLength(0);
  });

  // ── 2. Stuck task → re-enqueued ───────────────────────────────────────────

  it("re-enqueues a task with execution_handle older than EXECUTION_DEADLINE_MS", async () => {
    // Use a very short deadline so the 3h-old task triggers immediately.
    process.env.EXECUTION_DEADLINE_MS = "1"; // 1ms — everything is "stuck"

    const wsRoot = makeTmpDir("reconciler-stuck-");
    makeWorkspace(wsRoot, "my-feature", {
      id: "T1",
      status: "in_progress",
      execution_handle: "handle-abc",
      execution: {
        actor_type: "agent",
        last_updated_by: "test@test.com",
        last_updated_at: new Date(Date.now() - 10_000).toISOString(), // 10s ago
      },
    });

    const { emit } = emitCapture();

    // We can't test the full reconciler with git ops, so we mock appendLogEntry.
    // Instead test the re-enqueue path by checking executor.submit was called.
    // (The YAML git write would fail in a unit test context without a real repo.)
    // This test verifies the re-enqueue intent by checking broker.register +
    // executor.submit were called with the correct handle.

    // Since the reconciler does appendLogEntry which requires git, we test the
    // sub-components independently and verify the key call sequence here with
    // a workspace that has no git ops needed (the error is caught non-throwingly).

    // The test passes if executor.submit gets called with the task's handle.
    // Git commit errors are swallowed non-throwingly by appendLogEntry.
    try {
      await runDispatchReconciler({
        workspaceRoots: [wsRoot],
        executor: executor as never,
        broker: broker as never,
        workspacesDir: "/workspaces",
        callbackUrl: "http://broker:7000/callback",
        gitAuthorEmail: "test@test.com",
        emit,
      });
    } catch {
      // Git errors in appendLogEntry are swallowed — the test checks call counts.
    }

    // broker.register and executor.submit should have been called for "handle-abc"
    const reg = broker.registerCalls.find((r) => r.handle === "handle-abc");
    expect(reg).toBeDefined();

    const sub = executor.submitCalls.find((s) => s.handle === "handle-abc");
    expect(sub).toBeDefined();
    // nonce should be fresh (not the registered one from the initial submission)
    expect(sub!.taskId).toBe("T1");
  });

  // ── 3. Recent task → NOT re-enqueued ─────────────────────────────────────

  it("does NOT re-enqueue a task whose last_updated_at is within the deadline", async () => {
    process.env.EXECUTION_DEADLINE_MS = "999999999"; // very long deadline

    const wsRoot = makeTmpDir("reconciler-fresh-");
    makeWorkspace(wsRoot, "my-feature", {
      id: "T1",
      status: "in_progress",
      execution_handle: "handle-fresh",
      execution: {
        actor_type: "agent",
        last_updated_by: "test@test.com",
        last_updated_at: new Date().toISOString(), // just now
      },
    });

    const { emit } = emitCapture();

    const result = await runDispatchReconciler({
      workspaceRoots: [wsRoot],
      executor: executor as never,
      broker: broker as never,
      workspacesDir: "/workspaces",
      callbackUrl: "http://broker:7000/callback",
      gitAuthorEmail: "test@test.com",
      emit,
    });

    expect(result.reEnqueued).toBe(0);
    expect(result.blocked).toBe(0);
    expect(executor.submitCalls).toHaveLength(0);
    expect(broker.registerCalls).toHaveLength(0);
