/**
 * InMemoryBrokerAdapter — CompletionBrokerPort embedded in-process adapter.
 *
 * Wave 3 (T3): reference implementation of CompletionBrokerPort using
 * in-process state. Designed for the local-subprocess profile where the
 * broker lives in the same Node process as the orchestrator.
 *
 * Responsibilities:
 *  - In-flight registry: Map<handle, { nonce, metadata, registered_at }>
 *  - Completion queue with peek-and-lock + visibility timeout
 *  - HTTP receiver on POST /callback (validates nonce, enqueues completion)
 *  - Periodic reclaim sweep returning expired-lock items to the queue
 *
 * Lifecycle:
 *   const broker = new InMemoryBrokerAdapter();
 *   const port = await broker.start();  // binds HTTP, starts reclaim timer
 *   // ... use broker.register / listCompleted / ack / nack ...
 *   await broker.stop();               // stops HTTP server and reclaim timer
 */

import * as http from "node:http";
import * as crypto from "node:crypto";
import * as fs from "node:fs";
import * as path from "node:path";
import * as os from "node:os";
import type {
  CompletionBrokerPort,
  ExecutorHandle,
  HandleMetadata,
  ExecutorCompletion,
  ExecutorResult,
  RunnerCallbackPayload,
} from "@workflow/runtime-abi";

// ── Internal types ─────────────────────────────────────────────────────────────

interface RegistryEntry {
  nonce: string;
  metadata: HandleMetadata;
  registered_at: number;
}

interface QueueItem {
  handle: ExecutorHandle;
  result: ExecutorResult;
  metadata: HandleMetadata;
  locked_until?: number; // unix ms; absent means unlocked
}

// ── Defaults ──────────────────────────────────────────────────────────────────

const DEFAULT_LOCK_MS = 30_000;
const DEFAULT_RECLAIM_INTERVAL_MS = 2_000;
const DEFAULT_MAX = 10;

// ── InMemoryBrokerAdapter ─────────────────────────────────────────────────────

export interface InMemoryBrokerAdapterOpts {
  /**
   * Port to bind the HTTP receiver on. Pass 0 (default) for OS-assigned
   * ephemeral port — the chosen port is written to the runtime file and
   * returned from start().
   */
  port?: number;

  /** How often the reclaim sweep runs. Default: 2 000 ms. */
  reclaimIntervalMs?: number;

  /**
   * Path to write the chosen port number after binding.
   * Defaults to $XDG_RUNTIME_DIR/agent-broker.port or
   * os.tmpdir()/agent-broker.port.
   */
  portFilePath?: string;

  /** Clock used for timestamps (injected in tests). */
  clock?: { now(): number };
}

export class InMemoryBrokerAdapter implements CompletionBrokerPort {
  private readonly _clock: { now(): number };
  private readonly _reclaimIntervalMs: number;
  private readonly _bindPort: number;
  private readonly _portFilePath: string;

  private readonly registry = new Map<ExecutorHandle, RegistryEntry>();
  private readonly queue: QueueItem[] = [];

  private _server: http.Server | null = null;
  private _port: number | null = null;
  private _reclaimTimer: ReturnType<typeof setInterval> | null = null;

  constructor(opts: InMemoryBrokerAdapterOpts = {}) {
    this._clock = opts.clock ?? { now: () => Date.now() };
    this._reclaimIntervalMs = opts.reclaimIntervalMs ?? DEFAULT_RECLAIM_INTERVAL_MS;
    this._bindPort = opts.port ?? 0;

    const xdgRuntimeDir = process.env["XDG_RUNTIME_DIR"] ?? os.tmpdir();
    this._portFilePath = opts.portFilePath ?? path.join(xdgRuntimeDir, "agent-broker.port");
  }

