}
/**
 * Dispatch reconciler (T5 — standalone-executor-hardening).
 *
 * A backstop for the one case the dispatch stream can't self-heal: *no
 * dispatcher alive at all* so the job sits unclaimed and `XAUTOCLAIM` never
 * fires.
 *
 * Algorithm (per poll cycle):
 *   Scan all `in_progress` tasks with a persisted `execution_handle` whose
 *   `execution.last_updated_at` is older than EXECUTION_DEADLINE_MS.
 *
 *   For each stuck task:
 *     1. Count `reconciler_reenqueued` log entries. If count >= MAX_RETRIES,
 *        transition to `blocked` (reason: dispatch_reconciler_max_retries).
 *     2. Otherwise, generate a fresh nonce, re-register handle+nonce with the
 *        broker (overwrites stale nonce), re-submit via executor.submit().
 *        T4's per-handle spawn lock prevents double-spawn when a dispatcher
 *        IS alive but slow.
 *     3. Append a `reconciler_reenqueued` log entry and push the YAML.
 *
 * Only called from the poll loop when RUNTIME_PROFILE=local-docker.
 *
 * Environment:
 *   EXECUTION_DEADLINE_MS           ms after last_updated_at before a job is
 *                                   considered stuck. Default: 7 200 000 (2h).
 *   DISPATCH_RECONCILE_MAX_RETRIES  max re-enqueues before blocking.
 *                                   Default: 3.
 */

import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { randomUUID } from "node:crypto";
import { parse as parseYaml } from "yaml";
import type { CompletionBrokerPort, ExecutorPort, ExecutorPortInput } from "@workflow/runtime-abi";
import { DISPATCH_STREAM_KEY } from "@workflow/runtime-abi";
import {
  resolveRepoGitUrl,
  resolveRepoBaseBranch,
  parseManagementRepoCoords,
  loadWorkspaceModelPolicy,
} from "../config/workspace-config.js";
import { resolveModel } from "../config/resolve-model-policy.js";
import { taskYamlAbsPath, featureBranchName, workspaceYamlPath } from "../paths.js";
import { mutateTaskYamlDirect } from "../task/mutate-yaml-direct.js";
import { appendLogEntry } from "../task/append-log.js";
import { normalizeTaskKeyOrder } from "../utils/task-yaml-io.js";
import type { Task } from "../task/types.js";

// ── Constants (read at call time so tests can override via process.env) ────────

function getExecutionDeadlineMs(): number {
  return parseInt(process.env.EXECUTION_DEADLINE_MS ?? String(7_200_000), 10);
}

function getMaxRetries(): number {
  return parseInt(process.env.DISPATCH_RECONCILE_MAX_RETRIES ?? "3", 10);
}

// ── Types ─────────────────────────────────────────────────────────────────────

export interface DispatchReconcilerOpts {
  /** All workspace roots pulled this cycle. */
  workspaceRoots: string[];
  /** ExecutorPort (QueueDispatchAdapter on local-docker). */
  executor: ExecutorPort;
  /** Broker — used to re-register handle+nonce before re-enqueue. */
  broker: CompletionBrokerPort;
  /** Host directory under which per-handle workspace dirs live. */
  workspacesDir: string;
  /** Broker callback URL for re-enqueued jobs. */
  callbackUrl: string;
  /** Optional token budget forwarded to re-enqueued jobs. */
  budgetTokens?: number;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

export interface DispatchReconcilerResult {
  /** Tasks successfully re-enqueued. */
  reEnqueued: number;
  /** Tasks transitioned to blocked (retries exhausted). */
  blocked: number;
}

// ── Internal helpers ──────────────────────────────────────────────────────────

function readTaskSafe(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
): Task | null {
  try {
    const raw = parseYaml(
      readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
    ) as Record<string, unknown>;
    return normalizeTaskKeyOrder(raw);
  } catch {
    return null;
  }
}

function isExpiredDeadline(lastUpdatedAt: string | null | undefined): boolean {
  if (!lastUpdatedAt) return false;
  const updated = new Date(lastUpdatedAt).getTime();
  if (Number.isNaN(updated)) return false;
  return Date.now() - updated > getExecutionDeadlineMs();
}

function countReEnqueuedEntries(task: Task): number {
  return (task.log ?? []).filter(
    (e) => e.action === "reconciler_reenqueued",
  ).length;
}

/**
 * Discover all `in_progress` tasks with a persisted `execution_handle` whose
 * execution deadline has passed across the given workspace roots.
 */
function findStuckTasks(workspaceRoots: string[]): Array<{
  workspaceRoot: string;
  featureId: string;
  task: Task;
}> {
  const results: Array<{ workspaceRoot: string; featureId: string; task: Task }> = [];

  for (const wsRoot of workspaceRoots) {
    const featuresDir = join(wsRoot, "docs", "features");
    if (!existsSync(featuresDir)) continue;

    let featureDirs: string[];
    try {
      featureDirs = readdirSync(featuresDir, { withFileTypes: true })
        .filter((d) => d.isDirectory())
        .map((d) => d.name);
    } catch {
      continue;
    }

    for (const featureId of featureDirs) {
      const tasksDir = join(featuresDir, featureId, "tasks");
      if (!existsSync(tasksDir)) continue;

      let taskFiles: string[];
      try {
        taskFiles = readdirSync(tasksDir).filter((f) => f.endsWith(".yaml"));
      } catch {
        continue;
      }

      for (const taskFile of taskFiles) {
        const taskId = taskFile.replace(/\.yaml$/, "");
        const task = readTaskSafe(wsRoot, featureId, taskId);
        if (!task) continue;
        if (task.status !== "in_progress") continue;
        if (!task.execution_handle) continue;
        if (!isExpiredDeadline(task.execution?.last_updated_at)) continue;

        results.push({ workspaceRoot: wsRoot, featureId, task });
      }
    }
  }

  return results;
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Run one reconciler sweep. Call this from the poll loop on the local-docker
 * profile after the reap step.
 *
 * Non-throwing — individual errors are emitted as events.
 */
export async function runDispatchReconciler(
  opts: DispatchReconcilerOpts,
): Promise<DispatchReconcilerResult> {
  const {
    workspaceRoots,
    executor,
    broker,
    workspacesDir,
    callbackUrl,
    budgetTokens,
    gitAuthorEmail,
    gitAuthorName,
    sshKeyPath,
    emit,
  } = opts;

  let reEnqueued = 0;
  let blocked = 0;

  let stuckTasks: Array<{ workspaceRoot: string; featureId: string; task: Task }>;
  try {
    stuckTasks = findStuckTasks(workspaceRoots);
  } catch (e) {
    emit({ type: "reconciler_scan_error", details: String(e) });
    return { reEnqueued, blocked };
  }

  for (const { workspaceRoot, featureId, task } of stuckTasks) {
    const taskId = task.id;
    const handle = task.execution_handle as string;
    const taskBranch = task.branch;

    emit({
      type: "reconciler_stuck_task_detected",
      task_id: taskId,
      feature_id: featureId,
      handle,
      last_updated_at: task.execution?.last_updated_at,
      deadline_ms: getExecutionDeadlineMs(),
    });

    const retryCount = countReEnqueuedEntries(task);
    const maxRetries = getMaxRetries();

    // ── Retries exhausted → block ─────────────────────────────────────────
    if (retryCount >= maxRetries) {
      const mutateErr = mutateTaskYamlDirect({
        workspaceRoot,
        featureId,
        taskId,
        taskBranch,
        status: "blocked",
        logEntry: {
          action: "blocked",
          by: gitAuthorEmail,
          note: `Dispatch reconciler: no completion after ${retryCount} re-enqueues (max ${maxRetries}).`,
        },
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        commitMessage: `chore(${taskId}): reconciler — blocked after ${retryCount} re-enqueues`,
      });

      if (mutateErr) {
        emit({
          type: "reconciler_block_failed",
          task_id: taskId,
          feature_id: featureId,
          details: mutateErr,
        });
      } else {
        emit({
          type: "reconciler_task_blocked",
          task_id: taskId,
          feature_id: featureId,
          retries: retryCount,
          max: maxRetries,
        });
        blocked++;
      }
      continue;
    }

    // ── Resolve workspace context ─────────────────────────────────────────
    let taskRepoUrl: string;
    let taskRepoBaseBranch: string;
    let implModel: string;
    let mgmtRepoUrl: string;
    let workspaceId: string;

    try {
      taskRepoUrl = resolveRepoGitUrl(workspaceRoot, task.repo);
      taskRepoBaseBranch = resolveRepoBaseBranch(workspaceRoot, task.repo);
      const modelPolicy = loadWorkspaceModelPolicy(workspaceRoot);
      implModel = resolveModel(modelPolicy, {}, "implementation", taskId);
      mgmtRepoUrl = parseManagementRepoCoords(workspaceRoot).repoUrl;
      const wsYaml = parseYaml(
        readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
      ) as { workspace_id: string };
      workspaceId = wsYaml.workspace_id;
    } catch (e) {
      emit({
        type: "reconciler_context_error",
        task_id: taskId,
        feature_id: featureId,
        details: String(e),
      });
      continue;
    }

    // ── Re-register handle with a fresh nonce ─────────────────────────────
    const nonce = randomUUID();
    const startedAt = new Date().toISOString();

    try {
      await broker.register(handle, nonce, {
        kind: "impl",
        task_id: taskId,
        feature_id: featureId,
        started_at: startedAt,
      });
    } catch (e) {
      emit({
        type: "reconciler_register_failed",
        task_id: taskId,
        feature_id: featureId,
        details: String(e),
      });
      continue;
    }

    // ── Re-submit via executor (QueueDispatchAdapter → XADD) ──────────────
    // submit() calls broker.register() again — that is acceptable since
    // re-registration is idempotent (broker overwrites handle→nonce).
    const execInput: ExecutorPortInput = {
      taskId,
      featureId,
      workspaceId,
      handle,
      taskRepoUrl,
      taskRepoBranch: taskBranch,
      taskBaseBranch: featureBranchName(featureId),
      taskRepoBaseBranch,
      executorWorkdir: `${workspacesDir}/exec-${handle}`,
      mgmtRepoUrl,
      resultPath: `/tmp/executor-result-${taskId}.json`,
      callbackUrl,
      nonce,
      budgetTokens,
      implementationModel: implModel,
      sshPrivateKey: "",
      githubToken: "",
    };

    try {
      await executor.submit(execInput);
    } catch (e) {
      emit({
        type: "reconciler_reenqueue_failed",
        task_id: taskId,
        feature_id: featureId,
        handle,
        details: String(e),
      });
      continue;
    }

    emit({
      type: "reconciler_reenqueued",
      task_id: taskId,
      feature_id: featureId,
      handle,
      attempt: retryCount + 1,
      max: maxRetries,
      stream: DISPATCH_STREAM_KEY,
    });

    // ── Append log entry ──────────────────────────────────────────────────
    const logErr = appendLogEntry({
      workspaceRoot,
      featureId,
      taskId,
      taskBranch,
      entry: {
        action: "reconciler_reenqueued",
        by: gitAuthorEmail,
        note: `Dispatch reconciler: re-enqueued (attempt ${retryCount + 1} of ${maxRetries}).`,
        handle,
      },
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
    });

    if (logErr) {
      emit({
        type: "reconciler_log_failed",
        task_id: taskId,
        feature_id: featureId,
        details: logErr,
      });
    } else {
      reEnqueued++;
    }
  }

  return { reEnqueued, blocked };
}

