123	export class DispatchStreamConsumer {
124	  private readonly redis: RedisClientType;
125	  private readonly spawner: DockerSpawner;
126	  private readonly credential: CredentialAdapter;
127	  private readonly brokerUrl: string;
128	  private readonly consumerId: string;
129	  private readonly maxConcurrent: number;
130	  private readonly maxDeliveries: number;
131	  private readonly spawnLockTtlMs: number;
132	  private readonly pollBlockMs: number;
133	  private readonly xautoclaimMinIdleMs: number;
134	  private readonly batchSize: number;
135	
136	  private stopped = false;
137	
138	  constructor(opts: ConsumerOpts) {
139	    this.redis = opts.redis;
140	    this.spawner = opts.spawner;
141	    this.credential = opts.credential;
142	    this.brokerUrl = opts.brokerUrl;
143	    this.consumerId = opts.consumerId;
144	    this.maxConcurrent = opts.maxConcurrent;
145	    this.maxDeliveries = opts.maxDeliveries;
146	    this.spawnLockTtlMs = opts.spawnLockTtlMs;
147	    this.pollBlockMs = opts.pollBlockMs;
148	    this.xautoclaimMinIdleMs = opts.xautoclaimMinIdleMs;
149	    this.batchSize = opts.batchSize;
150	  }
151	
152	  /**
153	   * Ensure the consumer group exists on the dispatch stream.
154	   * Creates the stream + group if absent ($ = only new messages).
155	   */
156	  async ensureConsumerGroup(): Promise<void> {
157	    try {
158	      await this.redis.xGroupCreate(DISPATCH_STREAM_KEY, DISPATCH_CONSUMER_GROUP, "$", {
159	        MKSTREAM: true,
160	      });
161	      emit({ type: "consumer_group_created", group: DISPATCH_CONSUMER_GROUP });
162	    } catch (err) {
163	      // BUSYGROUP: group already exists — ignore.
164	      if (String(err).includes("BUSYGROUP")) return;
165	      throw err;
166	    }
167	  }
168	
169	  stop(): void {
170	    this.stopped = true;
171	  }
172	
173	  /**
174	   * Run the main dispatch loop until stop() is called.
175	   *
176	   * Each iteration:
177	   *   1. XAUTOCLAIM stuck pending entries.
178	   *   2. XREADGROUP for new entries.
179	   *   3. Process all collected entries.
180	   */
181	  async run(): Promise<void> {
182	    await this.ensureConsumerGroup();
