export class DispatchStreamConsumer {
  private readonly redis: RedisClientType;
  private readonly spawner: DockerSpawner;
  private readonly credential: CredentialAdapter;
  private readonly brokerUrl: string;
  private readonly consumerId: string;
  private readonly maxConcurrent: number;
  private readonly maxDeliveries: number;
  private readonly spawnLockTtlMs: number;
  private readonly pollBlockMs: number;
  private readonly xautoclaimMinIdleMs: number;
  private readonly batchSize: number;

  private stopped = false;

  constructor(opts: ConsumerOpts) {
    this.redis = opts.redis;
    this.spawner = opts.spawner;
    this.credential = opts.credential;
    this.brokerUrl = opts.brokerUrl;
    this.consumerId = opts.consumerId;
    this.maxConcurrent = opts.maxConcurrent;
    this.maxDeliveries = opts.maxDeliveries;
    this.spawnLockTtlMs = opts.spawnLockTtlMs;
    this.pollBlockMs = opts.pollBlockMs;
    this.xautoclaimMinIdleMs = opts.xautoclaimMinIdleMs;
    this.batchSize = opts.batchSize;
  }

  /**
   * Ensure the consumer group exists on the dispatch stream.
   * Creates the stream + group if absent ($ = only new messages).
   */
  async ensureConsumerGroup(): Promise<void> {
    try {
      await this.redis.xGroupCreate(DISPATCH_STREAM_KEY, DISPATCH_CONSUMER_GROUP, "$", {
        MKSTREAM: true,
      });
      emit({ type: "consumer_group_created", group: DISPATCH_CONSUMER_GROUP });
    } catch (err) {
      // BUSYGROUP: group already exists — ignore.
      if (String(err).includes("BUSYGROUP")) return;
      throw err;
    }
  }

  stop(): void {
    this.stopped = true;
  }

  /**
   * Run the main dispatch loop until stop() is called.
   *
   * Each iteration:
   *   1. XAUTOCLAIM stuck pending entries.
   *   2. XREADGROUP for new entries.
   *   3. Process all collected entries.
   */
  async run(): Promise<void> {
    await this.ensureConsumerGroup();

    while (!this.stopped) {
      try {
        // 1. Reclaim stuck entries (pending longer than xautoclaimMinIdleMs).
        const reclaimed = await this._xautoclaim();

        // 2. Read new entries (blocks up to pollBlockMs if none pending).
        const fresh = await this._xreadgroup();

        const entries = [...reclaimed, ...fresh];
        if (entries.length > 0) {
          await Promise.all(entries.map((e) => this._processEntry(e)));
        }
      } catch (err) {
        emit({ type: "consumer_loop_error", error: String(err) });
        // Brief back-off to avoid a tight error loop.
        await new Promise((r) => setTimeout(r, 1_000));
      }
    }
  }

  // ── Internal ───────────────────────────────────────────────────────────────

  private async _xautoclaim(): Promise<StreamEntry[]> {
    try {
      const result = await (this.redis as any).xAutoClaim(
        DISPATCH_STREAM_KEY,
        DISPATCH_CONSUMER_GROUP,
        this.consumerId,
        this.xautoclaimMinIdleMs,
        "0-0",
        { COUNT: this.batchSize },
      );
      // node-redis v4+ returns { nextId, messages }
      const messages: Array<{ id: string; message: Record<string, string> }> =
        result?.messages ?? [];
      return messages.map((m) => ({ id: m.id, message: m.message }));
    } catch (err) {
      // XAUTOCLAIM fails if the stream doesn't exist yet.
      if (String(err).includes("ERR no such key")) return [];
      emit({ type: "xautoclaim_error", error: String(err) });
      return [];
    }
  }

  private async _xreadgroup(): Promise<StreamEntry[]> {
    try {
      const results = await this.redis.xReadGroup(
        DISPATCH_CONSUMER_GROUP,
        this.consumerId,
        [{ key: DISPATCH_STREAM_KEY, id: ">" }],
        { COUNT: this.batchSize, BLOCK: this.pollBlockMs },
      );
      if (!results || results.length === 0) return [];
      const entries: StreamEntry[] = [];
      for (const stream of results) {
        for (const msg of stream.messages) {
          entries.push({ id: msg.id, message: msg.message as Record<string, string> });
        }
      }
      return entries;
    } catch (err) {
      emit({ type: "xreadgroup_error", error: String(err) });
      return [];
    }
  }

  /**
   * Get the delivery count for a pending entry.
   * Returns 1 if XPENDING-RANGE is unavailable (treat as first delivery).
   */
  async _getDeliveryCount(entryId: string): Promise<number> {
    try {
      const pending = await this.redis.xPendingRange(
        DISPATCH_STREAM_KEY,
        DISPATCH_CONSUMER_GROUP,
        entryId,
        entryId,
        1,
      );
      if (pending.length === 0) return 1;
      // node-redis v4+ uses `deliveriesCounter` for the delivery count field.
      const entry = pending[0] as { deliveriesCounter?: number; deliveryCount?: number };
      return entry.deliveriesCounter ?? entry.deliveryCount ?? 1;
    } catch {
      return 1;
    }
  }

  private async _processEntry(entry: StreamEntry): Promise<void> {

